const d = $json;
const wf = d.workflow || {};
const exec = d.execution || {};
const err = exec.error || d.error || {};

const wfName = wf.name || '(이름 없음)';
const wfId = wf.id || '';
const execId = exec.id || '';
const execUrl = exec.url || (wfId ? `n8n 실행 ID: ${execId}` : '');
const mode = exec.mode || '';
const lastNode = exec.lastNodeExecuted || err.node?.name || '(알 수 없음)';
const errMsg = (err.message || String(err) || '알 수 없는 오류').toString();
const when = new Date(exec.startedAt || Date.now()).toLocaleString('ko-KR');

const slackText = [
  ':rotating_light: *n8n 워크플로 실패*',
  `*워크플로:* ${wfName}`,
  `*실패 노드:* ${lastNode}`,
  `*에러:* ${errMsg}`,
  mode ? `*실행 모드:* ${mode}` : null,
  execUrl ? `*실행 링크:* ${execUrl}` : null,
  `*발생 시각:* ${when}`,
].filter(Boolean).join('\n');

return { json: { slackText, wfName, errMsg, lastNode } };
